import math

def mrr(test_set, search_fn, k=5):
    """Mean reciprocal rank: 1/rank of the first correct chunk, averaged (0 if not found)."""
    total = 0.0
    for case in test_set:
        for rank, cid in enumerate(search_fn(case["question"])[:k], start=1):
            if cid in case["relevant_ids"]:
                total += 1 / rank
                break
    return total / len(test_set)

def ndcg_at_k(ranked_ids, relevance, k=5):
    """relevance: {chunk_id: grade}, e.g. 2 = perfect, 1 = partly useful, missing = 0."""
    dcg = sum(relevance.get(cid, 0) / math.log2(i + 2) for i, cid in enumerate(ranked_ids[:k]))
    ideal = sorted(relevance.values(), reverse=True)[:k]
    idcg = sum(g / math.log2(i + 2) for i, g in enumerate(ideal))
    return dcg / idcg if idcg else 0.0

