def run_agent(question, user, tools, max_turns=8):
    messages = [{"role": "user", "content": question}]
    for turn in range(max_turns):                      # hard cap on turns
        resp = client.messages.create(model=MODEL, max_tokens=1024,
                                      tools=tools, messages=messages)
        log_trace(turn, resp)                          # save every step
        if resp.stop_reason != "tool_use":
            return "".join(b.text for b in resp.content if b.type == "text")
        messages.append({"role": "assistant", "content": resp.content})
        results = []
        for b in resp.content:
            if b.type == "tool_use":
                out = run_tool(b.name, b.input, user)
                results.append({"type": "tool_result", "tool_use_id": b.id, **out})
        messages.append({"role": "user", "content": results})
    return "Sorry, I could not finish this. A person will follow up."  # safe fallback

